import { collection, addDoc, getDocs, getDoc, updateDoc, deleteDoc, doc, serverTimestamp, query, orderBy, where, writeBatch, runTransaction } from 'firebase/firestore';
import { db } from '../firebase';

const PO_COLLECTION = 'purchaseOrders';
const ACTIVITY_COLLECTION = 'poActivity';

export function normalizePOForSave(raw) {
    const items = Array.isArray(raw.items) ? raw.items : [];
    // Normalize operations at PO level: accept `operations` array or single `operation`.
    // Also DERIVE union from each item's `operation` (string) and `operations` (array).
    let normalizedOperations = Array.isArray(raw.operations)
        ? raw.operations.filter(Boolean)
        : (raw.operation ? [String(raw.operation)] : []);
    if (items.length) {
        const perItemOps = [];
        items.forEach((it) => {
            if (!it) return;
            const single = it.operation ? String(it.operation).trim() : '';
            if (single) perItemOps.push(single);
            if (Array.isArray(it.operations)) {
                it.operations.filter(Boolean).forEach((op) => perItemOps.push(String(op).trim()));
            }
        });
        if (perItemOps.length) {
            const union = Array.from(new Set([...(normalizedOperations || []), ...perItemOps].filter(Boolean)));
            normalizedOperations = union;
        }
    }

    const safeItems = items.map((it) => {
        const quantity = Number(it.quantity) || 0;
        const unitPrice = Number(it.unitPrice ?? it.rate) || 0;
        return {
            description: String(it.description || '').trim(),
            quantity,
            unitPrice,
            amount: Number(it.amount ?? (quantity * unitPrice)).toFixed ? Number((quantity * unitPrice).toFixed(2)) : (quantity * unitPrice),
            unit: String(it.unit || 'pcs'),
            specifications: String(it.specifications || ''),
            deliveryDate: it.deliveryDate || '',
            itemId: it.itemId || null,
            // Per-item legacy single operation (optional)
            operation: it.operation || null,
            // New: per-item multi operations array
            operations: Array.isArray(it.operations) ? it.operations.filter(Boolean).map((op) => String(op)) : (it.operation ? [String(it.operation)] : []),
        };
    });

    const subtotal = safeItems.reduce((sum, it) => sum + (Number(it.amount) || 0), 0);
    const discountAmount = Number(raw.discountAmount || 0);
    const afterDiscount = subtotal - discountAmount;
    const taxRate = Number(raw.taxRate || 0);
    const taxAmount = (afterDiscount * taxRate) / 100;
    let finalAmount = afterDiscount + taxAmount;

    // Handle optional round-off like Delivery Challan form
    const roundOffEnabled = Boolean(raw.roundOffEnabled);
    let roundOffValue = Number(raw.roundOffValue || 0);
    if (roundOffEnabled) {
        const rounded = Math.round(finalAmount);
        roundOffValue = Number((rounded - finalAmount).toFixed(2));
        finalAmount = rounded;
    }

    // Initialize per-operation status maps ONLY for selected/normalized operations
    const operationsStatus = normalizedOperations.reduce((acc, op) => {
        acc[String(op)] = (raw.operationsStatus && raw.operationsStatus[op]) || 'pending';
        return acc;
    }, {});
    const operationsMeta = normalizedOperations.reduce((acc, op) => {
        const meta = (raw.operationsMeta && raw.operationsMeta[op]) || {};
        acc[String(op)] = {
            status: operationsStatus[String(op)] || 'pending',
            notes: meta.notes || '',
            updatedAt: meta.updatedAt || null,
            updatedBy: meta.updatedBy || null,
            startedAt: meta.startedAt || null,
            completedAt: meta.completedAt || null,
        };
        return acc;
    }, {});

    return {
        vendorId: String(raw.vendorId || '').trim(),
        // Keep legacy single operation for backward compatibility (first operation if any)
        operation: normalizedOperations[0] ? String(normalizedOperations[0]).trim() : '',
        // New multi-operations field
        operations: normalizedOperations,
        // New per-operation status fields
        operationsStatus,
        operationsMeta,
        description: String(raw.description || ''),
        deliveryDate: raw.deliveryDate ? (raw.deliveryDate instanceof Date ? raw.deliveryDate : new Date(raw.deliveryDate)) : null,
        priority: raw.priority || 'medium',
        status: raw.status || 'pending',
        paymentTerms: String(raw.paymentTerms ?? '30'),
        shippingAddress: String(raw.shippingAddress || ''),
        billingAddress: String(raw.billingAddress || ''),
        currency: raw.currency || 'INR',
        invoiceDate: raw.invoiceDate || null,
        dueDate: raw.dueDate || null,
        stateOfSupply: String(raw.stateOfSupply || ''),
        taxRate,
        discountAmount,
        items: safeItems,
        totalAmount: Number(subtotal.toFixed(2)),
        taxAmount: Number(taxAmount.toFixed(2)),
        finalAmount: Number(finalAmount.toFixed(2)),
        roundOffEnabled,
        roundOffValue,
        specifications: String(raw.specifications || ''),
        qualityRequirements: String(raw.qualityRequirements || ''),
        expectedDeliveryDays: Number(raw.expectedDeliveryDays || 0) || 0,
        warrantPeriod: String(raw.warrantPeriod || ''),
        terms: String(raw.terms || ''),
        poNumber: raw.poNumber || null,
    };
}

export function mapPOFromDoc(docSnap) {
    const d = docSnap.data() || {};
    return { id: docSnap.id, ...d };
}

async function logActivity(poId, action, details) {
	try {
		await addDoc(collection(db, ACTIVITY_COLLECTION), { poId, action, details: details || {}, timestamp: serverTimestamp() });
	} catch (_) {}
}

export async function getPOsOrdered() {
	const q = query(collection(db, PO_COLLECTION), orderBy('createdAt', 'desc'));
	const snap = await getDocs(q);
	return snap.docs.map(mapPOFromDoc);
}

export async function getPOById(id) {
	const snap = await getDoc(doc(db, PO_COLLECTION, id));
	if (!snap.exists()) return null;
	return mapPOFromDoc(snap);
}

export async function createPO(raw) {
    const data = normalizePOForSave(raw);
    data.createdAt = serverTimestamp();
    data.updatedAt = serverTimestamp();
    
    // Generate and assign PO number
    data.poNumber = await generatePONumber();
    
    const docRef = await addDoc(collection(db, PO_COLLECTION), data);
    await logActivity(docRef.id, 'created', { by: 'system' });
    return { id: docRef.id, ...data };
}

export async function updatePO(id, raw) {
	const data = normalizePOForSave(raw);
	await updateDoc(doc(db, PO_COLLECTION, id), { ...data, updatedAt: serverTimestamp() });
	await logActivity(id, 'update', { status: data.status });
}

export async function deletePO(id) {
	await deleteDoc(doc(db, PO_COLLECTION, id));
	await logActivity(id, 'delete');
}

export async function bulkUpdatePOs(ids, fields) {
	const batch = writeBatch(db);
	ids.forEach((id) => batch.update(doc(db, PO_COLLECTION, id), { ...fields, updatedAt: serverTimestamp() }));
	await batch.commit();
	for (const id of ids) logActivity(id, 'bulk_update', { fields });
}

export async function bulkDeletePOs(ids) {
	const batch = writeBatch(db);
	ids.forEach((id) => batch.delete(doc(db, PO_COLLECTION, id)));
	await batch.commit();
	for (const id of ids) logActivity(id, 'bulk_delete');
}

// Generate a structured PO number in format POYYYYDDMMXXX
async function generatePONumber() {
  const now = new Date();
  const year = now.getFullYear();
  const day = String(now.getDate()).padStart(2, '0');
  const month = String(now.getMonth() + 1).padStart(2, '0');
  
  // Reference to the counter document
  const counterRef = doc(db, 'counters', 'purchaseOrder');
  
  try {
    // Use a transaction to ensure atomic increment
    const result = await runTransaction(db, async (transaction) => {
      // Get the current counter
      const counterDoc = await transaction.get(counterRef);
      let sequence = 1;
      
      if (counterDoc.exists()) {
        // If counter exists, increment it
        const counterData = counterDoc.data();
        sequence = (counterData.lastSequence || 0) + 1;
        transaction.update(counterRef, { lastSequence: sequence });
      } else {
        // If counter doesn't exist, create it
        transaction.set(counterRef, { lastSequence: sequence });
      }
      
      // Format the sequence number with leading zeros
      const sequenceStr = String(sequence).padStart(3, '0');
      
      // Return the formatted PO number
      return `PO${year}${day}${month}${sequenceStr}`;
    });
    
    return result;
  } catch (error) {
    console.error('Error generating PO number:', error);
    // Fallback to timestamp if there's an error
    return `PO${year}${day}${month}${String(Date.now()).slice(-3)}`;
  }
}

// Fetch all POs with operations fields already mapped
export async function getAllPOsWithOperations() {
    const q = query(collection(db, PO_COLLECTION), orderBy('createdAt', 'desc'));
    const snap = await getDocs(q);
    return snap.docs.map(mapPOFromDoc);
}

// Update a single operation status for a specific item within a PO
// Aligns with EnhancedStatusManager expectations
export async function updatePOOperationStatus(poId, operation, itemIndex, newStatus, user = {}, notes = '') {
    if (poId == null || operation == null || itemIndex == null) {
        throw new Error('updatePOOperationStatus: missing required parameters');
    }

    const poRef = doc(db, PO_COLLECTION, poId);
    const snap = await getDoc(poRef);
    if (!snap.exists()) throw new Error('PO not found');

    const po = snap.data() || {};
    const items = Array.isArray(po.items) ? po.items : [];

    // Prepare nested structures
    const currentOpsStatus = po.operationsStatus || {};
    const itemStatusMap = currentOpsStatus[itemIndex] || {};
    const oldStatus = itemStatusMap[operation] || 'pending';

    const newItemStatusMap = { ...itemStatusMap, [operation]: newStatus };
    const newOperationsStatus = { ...currentOpsStatus, [itemIndex]: newItemStatusMap };

    // Meta key uses `${itemIndex}_${operation}` so UI can parse timeline
    const metaKey = `${itemIndex}_${operation}`;
    const currentMeta = po.operationsMeta || {};
    const itemDescription = items[itemIndex]?.description || '';
    const updatedBy = {
        uid: user?.uid || null,
        email: user?.email || null,
        name: user?.displayName || user?.name || null,
    };

    const newMetaEntry = {
        status: newStatus,
        oldStatus,
        notes: notes || '',
        updatedAt: serverTimestamp(),
        updatedBy,
        itemIndex,
        itemDescription,
    };

    // Optionally derive progress and overall status for convenience
    let progress = po.progress || 0;
    let derivedStatus = po.status || 'pending';
    try {
        let totalOps = 0;
        let completedOps = 0;
        (items || []).forEach((it, idx) => {
            const ops = [];
            if (Array.isArray(po.operations) && po.operations.length) {
                // If PO has declared operations, consider those
                ops.push(...po.operations);
            }
            if (it?.operation && !ops.includes(it.operation)) ops.push(it.operation);
            ops.forEach((op) => {
                totalOps += 1;
                const status = (idx === itemIndex && op === operation)
                    ? newStatus
                    : (newOperationsStatus?.[idx]?.[op] || 'pending');
                if (status === 'completed') completedOps += 1;
            });
        });
        progress = totalOps > 0 ? Math.round((completedOps / totalOps) * 100) : 0;
        if (totalOps > 0 && completedOps === totalOps) derivedStatus = 'completed';
        else if (completedOps > 0) derivedStatus = 'in_progress';
        else derivedStatus = 'pending';
    } catch (_) {}

    // Build update object with dotted paths
    const updatePayload = {
        [`operationsStatus.${itemIndex}`]: newItemStatusMap,
        [`operationsMeta.${metaKey}`]: newMetaEntry,
        updatedAt: serverTimestamp(),
        progress,
        status: derivedStatus,
    };

    await updateDoc(poRef, updatePayload);
    await logActivity(poId, 'operation_status_update', {
        operation,
        itemIndex,
        oldStatus,
        newStatus,
        notes,
    });

    return { ok: true };
}
